def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Panels separated by full lines of color 9.
    sep_rows = [r for r in range(h) if all(v == 9 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 9 for r in range(h))]
    if sep_rows or sep_cols:
        row_bounds = [-1] + sep_rows + [h]
        col_bounds = [-1] + sep_cols + [w]
        row_panels = [(row_bounds[i] + 1, row_bounds[i + 1])
                      for i in range(len(row_bounds) - 1)]
        col_panels = [(col_bounds[i] + 1, col_bounds[i + 1])
                      for i in range(len(col_bounds) - 1)]

        # The most populated panel supplies the repeated pattern.
        colors = {}
        for row in grid:
            for v in row:
                if v != 9:
                    colors[v] = colors.get(v, 0) + 1
        background = max(colors, key=colors.get) if colors else 0

        source = None
        best = -1
        for ri, (r0, r1) in enumerate(row_panels):
            for ci, (c0, c1) in enumerate(col_panels):
                count = sum(grid[r][c] != background
                            for r in range(r0, r1) for c in range(c0, c1))
                if count > best:
                    best, source = count, (ri, ci)

        if source is not None:
            sr0, sr1 = row_panels[source[0]]
            sc0, sc1 = col_panels[source[1]]
            for r0, r1 in row_panels:
                for c0, c1 in col_panels:
                    if r1 - r0 != sr1 - sr0 or c1 - c0 != sc1 - sc0:
                        continue
                    for dr in range(r1 - r0):
                        for dc in range(c1 - c0):
                            out[r0 + dr][c0 + dc] = grid[sr0 + dr][sc0 + dc]
        return out

    # Otherwise, repeat the tile marked by recurring monochrome columns.
    constant_cols = []
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            constant_cols.append((c, grid[0][c]))
    for i in range(len(constant_cols)):
        for j in range(i + 1, len(constant_cols)):
            c1, color1 = constant_cols[i]
            c2, color2 = constant_cols[j]
            period = c2 - c1
            if color1 == color2 and c1 == period - 1:
                for r in range(h):
                    for c in range(period, w):
                        out[r][c] = grid[r][c % period]
                return out
    return out
